import { ElevatorDisplayTypes } from "@/types/elevator";
import { elevatorDisplays } from "@/config/elevator/displayPresets";

export interface DisplayRenderData {
    floor: number;
    direction: "UP" | "DOWN" | "NONE";
    indicationColor?: string;
    offset?: number;
    [key: string]: any;
}

export const generateDisplaySVG = (
    displayType: ElevatorDisplayTypes,
    data: DisplayRenderData
): string => {
    const preset = elevatorDisplays[displayType];

    if (!preset) {
        console.warn(`Unknown display type: ${displayType}`);
        return "<svg></svg>";
    }

    if (typeof preset.render === "function") {
        return preset.render(data);
    }

    switch (displayType) {
        case "MLMLCD":
            return renderMLMLCD(preset, data);

        case "TIM2":
            return renderTIM2(preset, data);

        case "7SEGMENT_NEW":
            return render7SegmentNew(preset, data);

        default:
            return "<svg></svg>";
    }
};

function renderMLMLCD(preset: any, data: DisplayRenderData): string {
    const { floor, direction } = data;

    const digits = String(floor).padStart(2, " ");
    const left = digits[0];
    const right = digits[1];

    const leftSvg = preset.newSegment(left, -42);
    const rightSvg = preset.newSegment(right, 0);

    const arrowSvg =
        direction === "UP"
            ? `
                <path d="M173.1,210.78592l9.6,-30l10,36z" fill="#ffffff" />
                <path d="M152.1,216.78592l10.2,-35.8l9.4,29.8z" fill="#ffffff" />
            `
            : direction === "DOWN"
                ? `
                <path d="M171.7,148.92815l-9.4,29.8l-10.2,-35.8z" fill="#ffffff" />
                <path d="M193.07719,142.92815l-10,36l-9.6,-30z" fill="#ffffff" />
            `
                : "";

    return `
        <svg xmlns="http://www.w3.org/2000/svg" width="195" height="81" viewBox="0 0 195 81">
            <g transform="translate(-142,-140)">
                <path
                    d="M142.30925,216.37274c0,-15.26685 0,-62.68158 0,-71.35188c0,-2.66127 1.88138,-5.01693 4.45949,-5.01693c15.26374,0 159.29059,0 186.09916,0c2.75429,0 4.82286,2.35566 4.82286,5.01694c0,8.46892 0,53.90346 0,70.237c0,3.65524 -1.7159,5.85308 -4.82286,5.85308c-28.22121,0 -171.21207,0 -185.54172,0c-2.27579,0 -5.01693,-1.75561 -5.01693,-4.7382z"
                    fill="#00a6ff"
                />
                <path d="M162.7,179.78592l10,-31.2l9.8,30.8l-10.2,31.4z" fill="#ffffff" />
                ${arrowSvg}
                ${leftSvg}
                ${rightSvg}
            </g>
        </svg>
    `;
}


function renderTIM2(preset: any, data: DisplayRenderData): string {
    const { floor, direction, offset = 1 } = data;

    const current = String(floor).padStart(2, " ");
    const next = String((direction === "DOWN") ? floor - 1 : floor + 1).padStart(2, " ");
    const left = current[0];
    const right = current[1];

    const leftSvg = preset.showFloor(left, 7, offset);
    const rightSvg = preset.showFloor(right, 12, offset);

    const nextLeftSvg = preset.showFloor(next[0], 7, (direction === "DOWN" ? (offset + 8) : (offset - 8)));
    const nextRightSvg = preset.showFloor(next[1], 12, (direction === "DOWN" ? (offset + 8) : (offset - 8)));

    const arrowUp = direction !== "DOWN"
        ? `
            ${preset.activePoint(2, 2)}
            ${preset.activePoint(4, 2)}
            ${preset.activePoint(1, 3)}
            ${preset.activePoint(2, 3)}
            ${preset.activePoint(4, 3)}
            ${preset.activePoint(5, 3)}
        `
        : "";

    const arrowBase = `
        ${preset.activePoint(3, 1)}
        ${preset.activePoint(3, 2)}
        ${preset.activePoint(3, 3)}
        ${preset.activePoint(3, 4)}
        ${preset.activePoint(3, 5)}
        ${preset.activePoint(3, 6)}
        ${preset.activePoint(3, 7)}
    `;

    const arrowDown = direction !== "UP"
        ? `
            ${preset.activePoint(2, 6)}
            ${preset.activePoint(4, 6)}
            ${preset.activePoint(1, 5)}
            ${preset.activePoint(2, 5)}
            ${preset.activePoint(4, 5)}
            ${preset.activePoint(5, 5)}
        `
        : "";

    return `
        <svg xmlns="http://www.w3.org/2000/svg" width="189" height="80" viewBox="0 0 189 80">
            <g transform="translate(-142,-140)">
                <image x="285" y="281" transform="scale(0.5,0.5)" width="379" height="161" xlink:href="data:image/png;base64," fill="none" stroke="none" stroke-width="0.5"/>
                ${arrowUp}
                ${arrowBase}
                ${arrowDown}
                ${nextLeftSvg}
                ${nextRightSvg}
                ${leftSvg}
                ${rightSvg}
            </g>
        </svg>
    `;
}


function render7SegmentNew(preset: any, data: DisplayRenderData): string {
    const { floor, direction, indicationColor = "red" } = data;

    const digits = String(floor).padStart(2, " ");
    const left = digits[0];
    const right = digits[1];

    const leftSvg = preset.newSegment(left, 0, indicationColor);
    const rightSvg = preset.newSegment(right, 34, indicationColor);

    const arrowUp = preset.upArrow(direction === "UP", indicationColor);
    const arrowDown = preset.downArrow(direction === "DOWN", indicationColor);

    const bgFill = indicationColor === "blue" ? "#004278" : "#780000";

    return `
        <svg xmlns="http://www.w3.org/2000/svg" width="188" height="79" viewBox="0 0 188 79">
            <g transform="translate(-142,-140)">
                <path
                    d="M142.30925,214.80344c0,-14.95313 0,-61.39354 0,-69.88568c0,-2.60658 1.81704,-4.91383 4.30698,-4.91383c14.74176,0 153.84325,0 179.73504,0c2.6601,0 4.65793,2.30725 4.65793,4.91384c0,8.29489 0,52.79581 0,68.79371c0,3.58013 -1.65722,5.7328 -4.65793,5.7328c-27.25612,0 -165.35704,0 -179.19665,0c-2.19797,0 -4.84537,-1.71953 -4.84537,-4.64083z"
                    fill="${bgFill}"
                />
                ${leftSvg}
                ${rightSvg}
                ${arrowUp}
                ${arrowDown}
            </g>
        </svg>
    `;
}

